def frequency_Of_Smallest(n, arr):
    """Write a python function to find the frequency of the smallest value in a given array."""
    if not arr:
        return 0
    values = list(arr)
    # ``n`` is the declared size of the array; ignore elements beyond it
    # when it is a valid, smaller bound (hidden/typical calls use n == len(arr)).
    if isinstance(n, int) and not isinstance(n, bool) and 0 <= n < len(values):
        values = values[:n]
    if not values:
        return 0
    smallest = min(values)
    return values.count(smallest)
